from typing import Callable, Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")

class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T

class Err(TypedDict):
    ok: Literal[False]
    error: str


def parse_duration(s: str) -> Ok[int] | Err:
    """Parse a duration such as "1h30m15s" into seconds."""
    if not s:
        return {"ok": False, "error": "empty"}
    total = 0
    digits = ""
    last_rank = -1
    for ch in s:
        if ch in _DIGITS:
            digits += ch
